-- Correct only untouched synthetic fixtures generated by the earliest V1 seed.
-- The import snapshot is version 1; operational records and edited fixtures are preserved.
UPDATE app.orders o SET status='delivered'
FROM app.cases c
WHERE c.id=o.request_id AND c.data_origin='synthetic_history_v1'
  AND o.synthetic AND o.version=1 AND o.status='released'
  AND EXISTS(SELECT 1 FROM app.operator_events e WHERE e.case_id=c.id AND e.kind='delivery' AND e.actor_id='seed_demo');
